def lpHaarHistoryParent (n : ℕ) (h : Fin n → LpHaarFiniteSplit) : LpHaarFiniteParent :=
  if hn : n = 0 then LpHaarFiniteParent.root else
    (h ⟨(n - 1) / 2, by omega⟩).child (decide (n % 2 = 1))

